/// <summary>
///     Constructs a <c>METCustomerStatusChangeBusinessEventContract</c>.
/// </summary>
/// <returns>An instance of <c>METCustomerStatusChangeBusinessEventContract</c>.</returns>
public static METItemPackChangeCompletedBusinessEventContract newFromItemPackChangeCompleted(ItemId _itemId, METTempItemPackChg _tempItemPackChg, InventSiteId _inventSiteId)
{
    METItemPackChangeCompletedBusinessEventContract contract = new METItemPackChangeCompletedBusinessEventContract();
    contract.initialize(_itemId, _tempItemPackChg, _inventSiteId);
    return contract;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_items">List of items</param>
/// <returns>List of items</returns>
[DataMember('Item'), BusinessEventsDataMember("@SYS123828")]
public str parmItemId(itemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_items">List of items</param>
/// <returns>List of items</returns>
[DataMember('TempItemForPackChange'), BusinessEventsDataMember("@MET:TemporaryItemForPackChange")]
public str parmtempItemPackChg( METTempItemPackChg _tempItemPackChg = tempItemPackChg)
{
    tempItemPackChg = _tempItemPackChg;
    return tempItemPackChg;
}

/// <summary>
/// Site
/// </summary>
/// <param name = "_sites">List of Sites</param>
/// <returns>List of sites</returns>
[DataMember('Site'), BusinessEventsDataMember("@SYS103211")]
public str parmInventSiteId(str _inventSiteId = inventSiteId)
{
    inventSiteId = _inventSiteId;
    return inventSiteId;
}

/// <summary>
/// Initializes the data members
/// </summary>
/// <param name = "_custTable">the customer record</param>
private void initialize(ItemId _itemId, METTempItemPackChg _tempItemPackChg, InventSiteId _inventSiteId)
{
    tempItemPackChg = _tempItemPackChg;
    itemId = _itemId;
    inventSiteId = _inventSiteId;
}
